      "note": "Tô mì Quảng nóng hổi, đậm vị, ăn sáng là chuẩn bài của dân địa phương."
    },
    {
      "poi_id": "p211",
      "kind": "activity",
      "must_do_id": null,
      "note": "Phố cổ rêu phong, mái ngói cong cong, cứ thong thả mà ngắm từng góc nhỏ."
    },
    {
      "poi_id": "p208",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chùa Cầu soi bóng nước, đứng đây chụp một tấm là có ngay bức ảnh để đời."
    },
    {
      "poi_id": "p218",
      "kind": "meal",
      "must_do_id": null,
      "note": "Cao lầu sợi dai, nước sốt đậm, ăn kèm rau sống là hết sảy."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "Cát trắng, sóng hiền, nằm dài nghe biển hát là đúng điệu An Bàng."
    },
    {
      "poi_id": "p228",
      "kind": "meal",
      "must_do_id": null,
      "note": "Ngồi sát mép nước, gió biển thổi lồng lộng, hải sản tươi rói đưa lên."
    }
  ]
}
